on conflict (id) do update set
  kind = excluded.kind, name_ar = excluded.name_ar, name_en = excluded.name_en,
  color_group = excluded.color_group, price = excluded.price, mortgage_value = excluded.mortgage_value,
  build_cost = excluded.build_cost, rents = excluded.rents, tax_amount = excluded.tax_amount,
  position = excluded.position, grid_row = excluded.grid_row, grid_col = excluded.grid_col;
